webApi.a:expression:
a!localVariables(
  local!method: index(http!request.pathSegments, 1, null),
  local!body: #"SYSTEM_SYSRULES_fromJson_v1"(http!request.body),
  if(
    a!isNullOrEmpty(local!method),
    #"SYSTEM_SYSRULES_httpResponse_v1"(
      statusCode: 400,
      headers: {
        #"SYSTEM_SYSRULES_httpHeader"(
          name: "Content-Type",
          value: "application/json"
        )
      },
      body: #"SYSTEM_SYSRULES_toJson_v1"(
        a!map(
          success: false,
          error: "MISSING_METHOD",
          message: "URL path segment required. Valid methods: properties, query, create, update, delete"
        )
      )
    ),
    if(
      and(
        a!isNullOrEmpty(local!body.recordType),
        a!isNullOrEmpty(local!body.recordData)
      ),
      #"SYSTEM_SYSRULES_httpResponse_v1"(
        statusCode: 400,
        headers: {
          #"SYSTEM_SYSRULES_httpHeader"(
            name: "Content-Type",
            value: "application/json"
          )
        },
        body: #"SYSTEM_SYSRULES_toJson_v1"(
          a!map(
            success: false,
            error: "MISSING_PARAMETER",
            message: "recordType is required"
          )
        )
      ),
      a!match(
        value: local!method,
        equals: "properties",
        then: #"_a-0000efc0-b1bf-8000-9bbd-011c48011c48_56847"(recordTypeUuid: local!body.recordType),
        equals: "query",
        then: #"_a-0000efc0-b1bf-8000-9bbd-011c48011c48_56865"(
          recordTypeUuid: local!body.recordType,
          selectedFields: local!body.selectedFields,
          filters: local!body.filters,
          pagingInfo: local!body.pagingInfo
        ),
        equals: "create",
        then: #"_a-0000efc0-b1bf-8000-9bbd-011c48011c48_56884"(recordData: local!body.recordData),
        equals: "update",
        then: #"_a-0000efc0-b1bf-8000-9bbd-011c48011c48_56884"(recordData: local!body.recordData),
        equals: "delete",
        then: #"_a-0000efc0-b1bf-8000-9bbd-011c48011c48_56884"(recordData: local!body.recordData),
        default: #"SYSTEM_SYSRULES_httpResponse_v1"(
          statusCode: 404,
          headers: {
            #"SYSTEM_SYSRULES_httpHeader"(
              name: "Content-Type",
              value: "application/json"
            )
          },
          body: #"SYSTEM_SYSRULES_toJson_v1"(
            a!map(
              success: false,
              error: "INVALID_METHOD",
              message: "Unknown method: " & tostring(local!method) & ". Valid methods: properties, query, create, update, delete"
            )
          )
        )
      )
    )
  )
)
